def buscar_localidad(x:str):
    if not x:
        return []
    return [op for op in localidades if x.lower() in op.lower()]
if 'ip' not in st.session_state:
    try:
        session=boto3.Session(aws_access_key_id=st.secrets["ACCESS_KEY"],aws_secret_access_key=st.secrets["SECRET_ACCESS_KEY"],region_name='eu-north-1')
        st.session_state['ip']=session.client('ec2').describe_instances(Filters=[{'Name':'tag:Name','Values':['ServerPisos']}])['Reservations'][0]['Instances'][0]['NetworkInterfaces'][0]['Association']['PublicIp']
    except KeyError:
        st.session_state['ip']='127.0.0.1'
with tab1:
    col1,col2=st.columns(2)
    with col1:
        superficie_construida:int=st.number_input("Superficie construida (m²)",min_value=16,step=1,max_value=350)
        b,h=st.columns(2)
        banhos:int=b.number_input("Baños",min_value=0,step=1,max_value=6)
        habitaciones:int=h.number_input("Habitaciones",min_value=1,step=1,max_value=7)
        consumo=None
        emisiones=None
        if st.checkbox('Consumo y Emisiones'):
            c,e=st.columns(2)
            consumo=c.number_input("Consumo kWh/m² año",min_value=0.0,step=1.0)
            emisiones=e.number_input("Emisiones Kg CO₂/m² año",min_value=0.0,step=1.0)
        conservacion:str=st.selectbox("Conservación",options=conservaciones)
        localidad:str=st.selectbox("Localidad",options=localidades)
        localidad_formateada=localidad.lower().replace(' ','_').replace('-','_').replace('(','').replace(')','').replace('ü','u').replace('á','a').replace('é','e').replace('í','i').replace('ó','o').replace('ú','u').replace('ñ','n')
    with col2:
        with st.container(gap='xxsmall',horizontal_alignment='center'):
            if st.button('Predecir Precio',type='primary'):
                response:dict[str,Any]=json.loads(requests.post(url=f'http://{st.session_state['ip']}:8000/predict/',json=dict(superficie_construida=superficie_construida,banhos=banhos,habitaciones=habitaciones,consumo=consumo,emisiones=emisiones,conservacion=conservacion,localidad=localidad_formateada)).text)
                p=str(response['precio'])
                response['precio']=f"{'.'.join(p[::-1][i:i+3] for i in range(0,len(p),3))[::-1]} €"
                st.session_state['prediccion']=response
            if 'prediccion' in st.session_state:
                st.title(st.session_state['prediccion'].get('precio'),width='content',anchor=False)
                with st.container(gap='xxsmall',horizontal_alignment='left'):
                    st.subheader('Anuncios más parecidos')
                    for add in st.session_state['prediccion'].get('anuncios'):
                        st.write(f"- {add}")
with tab2:
    if 'historial' not in st.session_state:
        st.session_state['historial']=[]
        st.session_state['historial_consultas']=[]
    contenedor=st.container(horizontal_alignment='right')
    for mensaje in st.session_state['historial']:
        contenedor.chat_message(mensaje[0],width='content' if mensaje[0] in ['human','user'] else 'stretch').write(mensaje[1])
    with st.container(horizontal_alignment='center'):
        if request:=st.chat_input(width=600):
            contenedor.chat_message('human',width='content').write(request)
            def stream():
                fin=False
                historial_contador=0
                with requests.post(url=f'http://{st.session_state['ip']}:8000/ask/',json=dict(request=request,historial=st.session_state['historial'],historial_consultas=st.session_state['historial_consultas']),stream=True) as response:
                    for chunk in response.iter_content(chunk_size=None,decode_unicode=True):
                        if chunk:
                            if chunk=='FIN_DE_LA_RESPUESTA':
                                fin=True
                            elif fin:
                                chunk_json=json.loads(str(chunk).format(request=request))
                                chunk_json=[[x.replace('{','{{').replace('}','}}') for x in lista] for lista in chunk_json]
                                historial_a_extender='historial' if historial_contador==0 else 'historial_consultas'
                                st.session_state[historial_a_extender].extend(chunk_json)
                                historial_contador+=1
                            else:
                                yield chunk
            contenedor.chat_message('ai').write_stream(stream())